       <> (select coalesce(jsonb_agg(v order by v::text),'[]'::jsonb) from jsonb_array_elements('[{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"attempts"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"exam_results"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"match_preparations"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"notification_events"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"post_match_reviews"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"psychology_checkins"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"psychology_exercise_sessions"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"psychology_wellbeing_assessments"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"referee_exam_sessions"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"rules_exam_results"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"user_global_roles"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"user_profiles"},{"exists":true,"force":false,"installer_authority":true,"owner":"postgres","rls":true,"schema":"public","table":"user_subscriptions"}]'::jsonb) v)
     or (select coalesce(jsonb_agg(v order by v::text),'[]'::jsonb) from jsonb_array_elements((select jsonb_agg(v - 'raw_acl') from jsonb_array_elements(inventory->'columns') v)) v)
       <> (select coalesce(jsonb_agg(v order by v::text),'[]'::jsonb) from jsonb_array_elements('[{"schema":"public","table":"attempts","column":"accumulated_foul_correct"},{"schema":"public","table":"attempts","column":"activity_type"},{"schema":"public","table":"attempts","column":"answer_text"},{"schema":"public","table":"attempts","column":"assessment_session_id"},{"schema":"public","table":"attempts","column":"canonical_payload_hash"},{"schema":"public","table":"attempts","column":"clarity_score"},{"schema":"public","table":"attempts","column":"clip_id"},{"schema":"public","table":"attempts","column":"clip_title"},{"schema":"public","table":"attempts","column":"communication_mode"},{"schema":"public","table":"attempts","column":"communication_score"},{"schema":"public","table":"attempts","column":"correct_decision"},{"schema":"public","table":"attempts","column":"correct_discipline"},{"schema":"public","table":"attempts","column":"correct_restart"},{"schema":"public","table":"attempts","column":"created_at"},{"schema":"public","table":"attempts","column":"criterion_result"},{"schema":"public","table":"attempts","column":"difficulty"},{"schema":"public","table":"attempts","column":"disciplinary_correct"},{"schema":"public","table":"attempts","column":"discipline_correct"},{"schema":"public","table":"attempts","column":"discipline"},{"schema":"public","table":"attempts","column":"english_score"},{"schema":"public","table":"attempts","column":"exam_result_id"},{"schema":"public","table":"attempts","column":"feedback"},{"schema":"public","table":"attempts","column":"foul"},{"schema":"public","table":"attempts","column":"four_second_correct"},{"schema":"public","table":"attempts","column":"global_communication_label"},{"schema":"public","table":"attempts","column":"goalkeeper_correct"},{"schema":"public","table":"attempts","column":"grammar_score"},{"schema":"public","table":"attempts","column":"id"},{"schema":"public","table":"attempts","column":"institution_assess