  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.user_profiles r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.match_preparations r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.post_match_reviews r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.psychology_checkins r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.psychology_wellbeing_assessments r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.psychology_exercise_sessions r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.attempts r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.exam_results r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.rules_exam_results r),(select pg_catalog.md5(coalesce(
  pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by pg_catalog.to_jsonb(r)::text), '[]'::jsonb)::text)
  from public.notification_events r))::text),
    'protectedObjectsHash',pg_catalog.md5(jsonb_build_object(
      'functions',(select jsonb_agg(jsonb_build_array(p.oid,p.proowner,p.prolang,p.provolatile,
        p.proisstrict,p.prosecdef,p.proleakproof,p.prokind,p.proconfig,p.proacl,md5(p.prosrc)) order by p.oid)
        from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','reflab_private','reflab_audit')),
      'schemas',(select jsonb_agg(jsonb_build_array(oid,nspowner,nspacl) order by oid)
        from pg_namespace where nspname in ('public','reflab_private','reflab_meta','reflab_audit')),
      'indexes',(select jsonb_agg(jsonb_build_array(i.indexrelid,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) order by i.indexrelid)
        from pg_index i join relations r on r.oid=i.indrelid),
      'constraints',(select jsonb_agg(jsonb_build_array(c.oid,c.convalidated,pg_get_constraintdef(c.oid)) order by c.oid)
        from pg_constraint c join relations r on r.oid=c.conrelid),
      'triggers',(select jsonb_agg(jsonb_build_array(t.oid,t.tgenabled,pg_get_triggerdef(t.oid)) order by t.oid)
        from pg_trigger t join relations r on r.oid=t.tgrelid)
    )::text),
    'phase4Absent',not exists(select 1 from unnest(array['reflab_private.can_access_user_data(text, uuid, text)','reflab_private.has_active_institution_membership(uuid)','reflab_private.has_institution_permission(uuid, text)','reflab_private.protect_referee_exam_session()','reflab_private.set_updated_at()','reflab_private.validate_assessment_session_assignment()','reflab_private.validate_attempt_exam_context()','reflab_private.validate_exam_result_context()','reflab_private.validate_institution_data_consent()','reflab_private.validate_institution_role_scope()','reflab_private.validate_institution_user_target()','reflab_private.validate_owned_appointment()','reflab_private.validate_performance_checkin_owner()','reflab_private.validate_referee_exam_manifest()','reflab_private.validate_referee_exam_session_context()','reflab_private.validate_user_appointment_context()']::text[]) s
      where to_regprocedure(s) is not null) and not exists(select 1 from pg_description
      where description like 'reflab:production_adoption_provider=%'),
    'cutoverAbsent',to_regprocedure('reflab_private.set_updated_at()') is null
      and to_regrole('reflab_pre_cutover_evidence_owner') is null,
    'runtimeDisabled',(select count(*)=0 from reflab_meta.reflab_schema_state)
  )
)) - 'table_acl' - 'column_acl',
  'identity',pg_catalog.jsonb_build_object(
  'functions', (select jsonb_agg(jsonb_build_object(
    'signature', n.nspname || '.' || p.proname || '()', 'identity_arguments', pg_get_function_identity_arguments(p.oid),
    'result_type', pg_get_function_result(p.oid), 'language', l.lanname, 'volatility', p.provolatile,
    'strict', p.proisstrict, 'security_definer', p.prosecdef, 'leakproof', p.proleakproof, 'kind', p.prokind,
    'owner', pg_get_userbyid(p.proowner), 'configuration', p.proconfig, 'proacl', p.proacl,
    'source_hash', encode(extensions.digest(convert_to(pg_catalog.regexp_replace(
      p.prosrc,'^[[:space:]]+|[[:space:]]+$','','g'),'UTF8'),'sha256'),'hex')) order by n.nspname,p.proname)
    from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    join pg_catalog.pg_language l on l.oid=p.prolang
    where p.oid in (select to_regprocedure(s) from unnest(array['reflab_private.request_user_id()','reflab_private.is_super_admin()','public.institution_request_user_id()','public.platform_request_user_id()','public.reflab_request_user_id()']) s)),
  'acl', (select jsonb_agg(jsonb_build_object('signature', n.nspname || '.' || p.proname || '()',
    'grantee', case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,
    'grantor', pg_get_userbyid(a.grantor), 'privilege', a.privilege_type, 'grantable', a.is_grantable)
    order by n.nspname,p.proname,a.grantee,a.grantor)
    from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    cross join lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
    where p.oid in (select to_regprocedure(s) from unnest(array['reflab_private.request_user_id()','reflab_private.is_super_admin()','public.institution_request_user_id()','public.platform_request_user_id()','public.reflab_request_user_id()']) s)),
  'rls_owner_create', has_schema_privilege('reflab_rls_owner','public','CREATE')
    or has_schema_privilege('reflab_rls_owner','reflab_private','CREATE'),
  'ledger_rows', (select count(*) from reflab_meta.production_adoption_state),
  'schema_state_rows', (select count(*) from reflab_meta.reflab_schema_state)
),'adoption',(
  select pg_catalog.jsonb_build_object(
    'ledgerRows', (select coalesce(jsonb_agg(to_jsonb(s) order by s.phase_order),'[]'::jsonb)
      from reflab_meta.production_adoption_state s),
    'schemaStateRows', (select coalesce(jsonb_agg(to_jsonb(s) order by to_jsonb(s)::text),'[]'::jsonb)
      from reflab_meta.reflab_schema_state s),
    'canonicalMarkerAbsent', (select count(*)=0 from reflab_meta.reflab_schema_state),
    'historicalCounts', jsonb_build_object(
      'attempts',(select count(*) from public.attempts),
      'exam_results',(select count(*) from public.exam_results),
      'notification_events',(select count(*) from public.notification_events),
      'clips',(select count(*) from public.clips)),
    'developmentObjects', jsonb_build_object(
      'reflab_private.user_identity_links',to_regclass('reflab_private.user_identity_links') is not null,
      'public.resolve_development_clerk_identity(text)',to_regprocedure('public.resolve_development_clerk_identity(text)') is not null,
      'public.link_development_clerk_identity(text)',to_regprocedure('public.link_development_clerk_identity(text)') is not null,
      'public.link_development_super_admin_clerk_identity(text)',to_regprocedure('public.link_development_super_admin_clerk_identity(text)') is not null),
    'schemaCreatePrivileges', (select jsonb_agg(jsonb_build_object(
      'schema',n.nspname,'role',r.rolname,'create',has_schema_privilege(r.oid,n.oid,'CREATE'))
      order by n.nspname,r.rolname) from pg_namespace n cross join pg_roles r
      where n.nspname in ('public','reflab_private')
        and r.rolname in ('postgres','reflab_rls_owner','anon','authenticated'))
  )
)) then
    raise exception '64249 preservation failure' using errcode='55000';
  end if;
  -- referee_exam_sessions SELECT ACL is intentionally inert: its authenticated policy is absent.
  -- Historical INSERT policies stay defined, but browser INSERT authority is now absent.
end
$browser_transition$;
commit;
